    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure or error reported by an earlier execution step.",
      "source_description": "An earlier observed execution failure or error condition (e.g., a non-zero exit status, a build abort, or an unsupported-tool message).",
      "target_description": "A subsequent agent action intended to correct or work around that failure."
    },
    {
      "name": "INVESTIGATES_FAILURE",
      "definition": "An agent action examines diagnostic information (logs, error sections, installed-state listings) in order to determine the cause of an earlier observed failure.",
      "source_description": "An earlier observed execution failure or error condition whose cause is not yet understood.",
      "target_description": "A diagnostic agent action that inspects logs, error details, or environment state to localize the cause."
    },
    {
      "name": "POLLS_RUNNING_TASK",
      "definition": "A subsequent agent action checks the status or progress of a previously launched long-running background task, often repeatedly, before proceeding.",
      "source_description": "A previously launched long-running background task whose completion is pending.",
      "target_description": "A status-checking agent action (e.g., waiting then inspecting the task's log or job list) used to determine whether the task has progressed or finished."
    }
  ]
}

